    h,w=len(I),len(I[0])
    for i in range(h):
        for j in range(w):
            if I[i][j]==val and (i,j) not in seen:
                stack=[(i,j)]; seen.add((i,j)); cells=[]
                while stack:
                    a,b=stack.pop(); cells.append((a,b))
                    for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
